tool_input.old_string:
// 顶部始终可见的横向滚动条（与表体 scrollLeft 同步）
.stat-table-xbar {
  flex: 0 0 auto;
  overflow-x: auto;
  overflow-y: hidden;
  height: 12px;
  margin-bottom: 2px;

  .stat-table-xbar-inner {
    height: 1px;
  }
}

// 仅表体区域纵向滚动；横向由顶栏滚动条操作（底栏隐藏横向条避免双轨）
.stat-table-wrap {
  flex: 1 1 0%;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}

tool_input.new_string:
// 顶部始终可见的横向滚动条（与表体 scrollLeft 同步；scroll 强制常显）
.stat-table-xbar {
  flex: 0 0 auto;
  overflow-x: scroll;
  overflow-y: hidden;
  height: 16px;
  margin-bottom: 4px;
  scrollbar-gutter: stable;

  .stat-table-xbar-inner {
    height: 1px;
  }
}

// 仅表体区域纵向滚动，scrollbar 始终显示；横向由顶栏条操作
.stat-table-wrap {
  flex: 1 1 0%;
  min-height: 0;
  overflow-y: scroll;
  overflow-x: hidden;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-gutter: stable;
}
